create extension if not exists pgcrypto;
create table if not exists public.profiles (id uuid primary key references auth.users(id) on delete cascade,username text unique not null,display_name text not null,role text not null check (role in ('client','admin')),org_name text,created_at timestamptz not null default now());
create table if not exists public.activities (id uuid primary key default gen_random_uuid(),owner_id uuid not null references public.profiles(id) on delete cascade,org_name text not null,title text not null,category text not null default 'Taller',event_date date not null,event_time time not null,area text not null,address text,price integer not null default 0 check (price>=0),capacity integer not null check (capacity>0),reserved_count integer not null default 0 check (reserved_count>=0),status text not null default 'active' check (status in ('active','paused','cancelled')),description text,includes text,policy text,created_at timestamptz not null default now());
create table if not exists public.reservations (id uuid primary key default gen_random_uuid(),activity_id uuid not null references public.activities(id) on delete cascade,client_id uuid not null references public.profiles(id) on delete cascade,client_name text not null,client_username text not null,qty integer not null default 1 check (qty>0),status text not null default 'confirmed' check (status in ('confirmed','cancelled')),attendance boolean not null default false,from_waitlist boolean not null default false,reason text,created_at timestamptz not null default now());
create table if not exists public.waitlist (id uuid primary key default gen_random_uuid(),activity_id uuid not null references public.activities(id) on delete cascade,client_id uuid not null references public.profiles(id) on delete cascade,client_name text not null,client_username text not null,status text not null default 'waiting' check (status in ('waiting','promoted','left')),created_at timestamptz not null default now());
create table if not exists public.favorites (client_id uuid not null references public.profiles(id) on delete cascade,activity_id uuid not null references public.activities(id) on delete cascade,created_at timestamptz not null default now(),primary key(client_id,activity_id));
create index if not exists activities_owner_idx on public.activities(owner_id);create index if not exists reservations_activity_idx on public.reservations(activity_id);create index if not exists reservations_client_idx on public.reservations(client_id);create index if not exists waitlist_activity_idx on public.waitlist(activity_id);create index if not exists waitlist_client_idx on public.waitlist(client_id);
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,username,display_name,role,org_name) values(new.id,lower(coalesce(new.raw_user_meta_data->>'username','usuario')),coalesce(new.raw_user_meta_data->>'display_name','Usuario'),case when new.raw_user_meta_data->>'role'='admin' then 'admin' else 'client' end,nullif(new.raw_user_meta_data->>'org_name',''));return new;end;$$;
drop trigger if exists on_auth_user_created on auth.users;create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
alter table public.profiles enable row level security;alter table public.activities enable row level security;alter table public.reservations enable row level security;alter table public.waitlist enable row level security;alter table public.favorites enable row level security;
revoke all on public.profiles,public.activities,public.reservations,public.waitlist,public.favorites from anon,authenticated;grant select on public.activities to anon,authenticated;grant select,update on public.profiles to authenticated;grant insert,update,delete on public.activities to authenticated;grant select,update on public.reservations to authenticated;grant select on public.waitlist to authenticated;grant select,insert,delete on public.favorites to authenticated;
drop policy if exists profiles_own_select on public.profiles;create policy profiles_own_select on public.profiles for select to authenticated using((select auth.uid())=id);drop policy if exists profiles_own_update on public.profiles;create policy profiles_own_update on public.profiles for update to authenticated using((select auth.uid())=id) with check((select auth.uid())=id);
drop policy if exists activities_public_select on public.activities;create policy activities_public_select on public.activities for select to anon using(status='active');drop policy if exists activities_auth_select on public.activities;create policy activities_auth_select on public.activities for select to authenticated using(status='active' or owner_id=(select auth.uid()));drop policy if exists activities_admin_insert on public.activities;create policy activities_admin_insert on public.activities for insert to authenticated with check(owner_id=(select auth.uid()) and exists(select 1 from public.profiles p where p.id=(select auth.uid()) and p.role='admin'));drop policy if exists activities_admin_update on public.activities;create policy activities_admin_update on public.activities for update to authenticated using(owner_id=(select auth.uid())) with check(owner_id=(select auth.uid()));drop policy if exists activities_admin_delete on public.activities;create policy activities_admin_delete on public.activities for delete to authenticated using(owner_id=(select auth.uid()));
drop policy if exists reservations_client_or_owner_select on public.reservations;create policy reservations_client_or_owner_select on public.reservations for select to authenticated using(client_id=(select auth.uid()) or exists(select 1 from public.activities a where a.id=activity_id and a.owner_id=(select auth.uid())));drop policy if exists reservations_owner_update on public.reservations;create policy reservations_owner_update on public.reservations for update to authenticated using(exists(select 1 from public.activities a where a.id=activity_id and a.owner_id=(select auth.uid()))) with check(exists(select 1 from public.activities a where a.id=activity_id and a.owner_id=(select auth.uid())));
drop policy if exists waitlist_client_or_owner_select on public.waitlist;create policy waitlist_client_or_owner_select on public.waitlist for select to authenticated using(client_id=(select auth.uid()) or exists(select 1 from public.activities a where a.id=activity_id and a.owner_id=(select auth.uid())));
drop policy if exists favorites_own_select on public.favorites;create policy favorites_own_select on public.favorites for select to authenticated using(client_id=(select auth.uid()));drop policy if exists favorites_own_insert on public.favorites;create policy favorites_own_insert on public.favorites for insert to authenticated with check(client_id=(select auth.uid()));drop policy if exists favorites_own_delete on public.favorites;create policy favorites_own_delete on public.favorites for delete to authenticated using(client_id=(select auth.uid()));
create or replace function public.reserve_activity(p_activity uuid,p_qty integer default 1) returns uuid language plpgsql security definer set search_path=public as $$ declare a public.activities%rowtype;p public.profiles%rowtype;rid uuid;begin if auth.uid() is null then raise exception 'Debes iniciar sesión para reservar.';end if;if p_qty<1 or p_qty>4 then raise exception 'Cantidad de cupos no válida.';end if;select * into p from public.profiles where id=auth.uid();if p.role<>'client' then raise exception 'Solo una cuenta de cliente puede reservar.';end if;select * into a from public.activities where id=p_activity for update;if not found or a.status<>'active' then raise exception 'Esta actividad no está disponible.';end if;if exists(select 1 from public.reservations where activity_id=p_activity and client_id=auth.uid() and status='confirmed') then raise exception 'Ya tienes una reserva confirmada para esta actividad.';end if;if a.reserved_count+p_qty>a.capacity then raise exception 'No quedan suficientes cupos.';end if;insert into public.reservations(activity_id,client_id,client_name,client_username,qty) values(p_activity,auth.uid(),p.display_name,p.username,p_qty) returning id into rid;update public.activities set reserved_count=reserved_count+p_qty where id=p_activity;update public.waitlist set status='promoted' where activity_id=p_activity and client_id=auth.uid() and status='waiting';return rid;end;$$;
create or replace function public.join_waitlist(p_activity uuid) returns uuid language plpgsql security definer set search_path=public as $$ declare a public.activities%rowtype;p public.profiles%rowtype;wid uuid;begin if auth.uid() is null then raise exception 'Debes iniciar sesión.';end if;select * into p from public.profiles where id=auth.uid();if p.role<>'client' then raise exception 'Solo una cuenta de cliente puede entrar a la lista.';end if;select * into a from public.activities where id=p_activity;if not found or a.status<>'active' then raise exception 'La actividad no está disponible.';end if;if a.reserved_count<a.capacity then raise exception 'Todavía quedan cupos; puedes reservar directamente.';end if;if exists(select 1 from public.reservations where activity_id=p_activity and client_id=auth.uid() and status='confirmed') then raise exception 'Ya tienes una reserva.';end if;if exists(select 1 from public.waitlist where activity_id=p_activity and client_id=auth.uid() and status='waiting') then raise exception 'Ya estás en la lista de espera.';end if;insert into public.waitlist(activity_id,client_id,client_name,client_username) values(p_activity,auth.uid(),p.display_name,p.username) returning id into wid;return wid;end;$$;
create or replace function public.cancel_reservation(p_reservation uuid) returns void language plpgsql security definer set search_path=public as $$ declare r public.reservations%rowtype;a public.activities%rowtype;w public.waitlist%rowtype;begin if auth.uid() is null then raise exception 'Debes iniciar sesión.';end if;select * into r from public.reservations where id=p_reservation and client_id=auth.uid() for update;if not found or r.status<>'confirmed' then raise exception 'Reserva no disponible para cancelar.';end if;select * into a from public.activities where id=r.activity_id for update;update public.reservations set status='cancelled',reason='Cancelada por el cliente' where id=r.id;update public.activities set reserved_count=greatest(0,reserved_count-r.qty) where id=a.id;a.reserved_count:=greatest(0,a.reserved_count-r.qty);while a.status='active' and a.reserved_count<a.capacity loop select * into w from public.waitlist where activity_id=a.id and status='waiting' order by created_at limit 1 for update skip locked;exit when not found;update public.waitlist set status='promoted' where id=w.id;insert into public.reservations(activity_id,client_id,client_name,client_username,qty,status,from_waitlist) values(a.id,w.client_id,w.client_name,w.client_username,1,'confirmed',true);a.reserved_count:=a.reserved_count+1;update public.activities set reserved_count=a.reserved_count where id=a.id;end loop;end;$$;
create or replace function public.leave_waitlist(p_waitlist uuid) returns void language plpgsql security definer set search_path=public as $$ begin update public.waitlist set status='left' where id=p_waitlist and client_id=auth.uid() and status='waiting';end;$$;
create or replace function public.cancel_activity(p_activity uuid) returns void language plpgsql security definer set search_path=public as $$ begin if not exists(select 1 from public.activities where id=p_activity and owner_id=auth.uid()) then raise exception 'No autorizado.';end if;update public.activities set status='cancelled',reserved_count=0 where id=p_activity;update public.reservations set status='cancelled',reason='Actividad cancelada por el organizador' where activity_id=p_activity and status='confirmed';update public.waitlist set status='left' where activity_id=p_activity and status='waiting';end;$$;
create or replace function public.admin_promote_waitlist(p_waitlist uuid) returns uuid language plpgsql security definer set search_path=public as $$ declare w public.waitlist%rowtype;a public.activities%rowtype;rid uuid;begin select * into w from public.waitlist where id=p_waitlist and status='waiting' for update;if not found then raise exception 'Registro no disponible.';end if;select * into a from public.activities where id=w.activity_id for update;if a.owner_id<>auth.uid() then raise exception 'No autorizado.';end if;if a.status<>'active' or a.reserved_count>=a.capacity then raise exception 'No hay cupos disponibles.';end if;insert into public.reservations(activity_id,client_id,client_name,client_username,qty,status,from_waitlist) values(a.id,w.client_id,w.client_name,w.client_username,1,'confirmed',true) returning id into rid;update public.waitlist set status='promoted' where id=w.id;update public.activities set reserved_count=reserved_count+1 where id=a.id;return rid;end;$$;
revoke all on function public.reserve_activity(uuid,integer) from public;revoke all on function public.join_waitlist(uuid) from public;revoke all on function public.cancel_reservation(uuid) from public;revoke all on function public.leave_waitlist(uuid) from public;revoke all on function public.cancel_activity(uuid) from public;revoke all on function public.admin_promote_waitlist(uuid) from public;grant execute on function public.reserve_activity(uuid,integer) to authenticated;grant execute on function public.join_waitlist(uuid) to authenticated;grant execute on function public.cancel_reservation(uuid) to authenticated;grant execute on function public.leave_waitlist(uuid) to authenticated;grant execute on function public.cancel_activity(uuid) to authenticated;grant execute on function public.admin_promote_waitlist(uuid) to authenticated;
